// AUTO-GENERATED by pipeline/wiki.py – Wikipedia summaries (CC BY-SA) and Wikimedia Commons photos (credited)
window.TW_WIKI = {"atacama_yungay": {"en": {"title": "Atacama Desert", "extract": "The Atacama Desert is a desert plateau on the Pacific coast of South America, stretching along a 1,600-kilometre-long (1,000-mile) strip of land in northern Chile, west of the Andes. It covers an area of 105,000 km2 (41,000 mi2), rising to 128,000 km2 (49,000 mi2) if the barren lower slopes of the Andes are included.", "url": "https://en.wikipedia.org/wiki/Atacama_Desert"}, "es": {"title": "Desierto de Atacama", "extract": "El desierto de Atacama se extiende por una franja de la costa Pacífica de América del Sur. Abarca a dos países: Chile y Perú. Tiene una superficie aproximada de 105 000 km², una longitud de casi 1600 km y un ancho máximo de 180 km. Está delimitado por el océano Pacífico al oeste y por la cordillera de los Andes al este. Forma parte de la ecorregión denominada desierto del Pacífico. Se le considera el «lugar no polar más árido de la Tierra».", "url": "https://es.wikipedia.org/wiki/Desierto_de_Atacama"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Paisaje_en_el_desierto_de_Atacama%2C_Chile%2C_2016-02-06%2C_DD_16.JPG/960px-Paisaje_en_el_desierto_de_Atacama%2C_Chile%2C_2016-02-06%2C_DD_16.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Paisaje_en_el_desierto_de_Atacama,_Chile,_2016-02-06,_DD_16.JPG", "author": "Diego Delso", "license": "CC BY-SA 4.0", "file": "File:Paisaje en el desierto de Atacama, Chile, 2016-02-06, DD 16.JPG"}}, "haughton": {"en": {"title": "Haughton impact crater", "extract": "Haughton impact crater is located on Devon Island, Nunavut in far Northern Canada. It is about 23 km (14 mi) in diameter and was formed 31–32 million years ago during the Early Oligocene. The impacting object is estimated to have been approximately 2 km (1.2 mi) in diameter. Devon Island itself is composed of Paleozoic shale and siltstone overlying gneissic bedrock. When the crater formed, the shale and siltstone were peeled back to expose the basement; material from as deep as 1,700 m (5,600 ft) has been identified.", "url": "https://en.wikipedia.org/wiki/Haughton_impact_crater"}, "es": null, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Rovers_Red_and_Black_at_Houghton_Crater_Devon_Island_Canada.jpg/960px-Rovers_Red_and_Black_at_Houghton_Crater_Devon_Island_Canada.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Rovers_Red_and_Black_at_Houghton_Crater_Devon_Island_Canada.jpg", "author": "NASA", "license": "Public domain", "file": "File:Rovers Red and Black at Houghton Crater Devon Island Canada.jpg"}}, "death_valley": {"en": {"title": "Death Valley", "extract": "Death Valley is a desert valley in Eastern California, United States, in the northern Mojave Desert, bordering the Great Basin Desert. The World Meteorological Organization lists Death Valley as the site of the hottest surface temperature recorded on Earth.", "url": "https://en.wikipedia.org/wiki/Death_Valley"}, "es": {"title": "Valle de la Muerte", "extract": "El valle de la Muerte es un valle desértico ubicado al sureste de California, en el desierto de Mojave, limítrofe del sur del desierto de la Gran Cuenca. En verano es uno de los lugares más calurosos del mundo, junto con los desiertos de Sonora, Danakil, Victoria y Lut.", "url": "https://es.wikipedia.org/wiki/Valle_de_la_Muerte"}, "photo": {"src": "https://upload.wikimedia.org/wikipedia/commons/9/98/Death_Valley_from_space.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "page": "https://commons.wikimedia.org/wiki/File:Death_Valley_from_space.JPG", "author": "NASA", "license": "Public domain", "file": "File:Death_Valley_from_space.JPG"}}, "mcmurdo_dry_valleys": {"en": {"title": "McMurdo Dry Valleys", "extract": "The McMurdo Dry Valleys are a series of largely snow-free desert valleys on the continental coastline of Victoria Land, Antarctica, east of the East Antarctic Ice Sheet and west of McMurdo Sound and the Ross Sea. The Dry Valleys are the coldest and driest desert in the world, and the largest ice-free region in Antarctica; as a result, the Valleys have become a hotbed for scientific research in the Antarctic region. The Dry Valleys' climate is due to their location nestled within the Transantarctic Mountains along with high-pressure katabatic winds that scour away snowfall and humidity across the region. Surrounding mountains prevent the flow of ice from nearby glaciers. The region's geology is primarily granites and gneisses, and glacial tills dot the bedrock landscape, with loose gravel covering the ground. The Valleys are one of the driest places on Earth, though there are several anecdotal accounts of rainfall within them.", "url": "https://en.wikipedia.org/wiki/McMurdo_Dry_Valleys"}, "es": {"title": "Valles secos de McMurdo", "extract": "Los valles secos de McMurdo o Valles Secos son un conjunto de valles que se encuentran en las proximidades del estrecho de McMurdo, en la tierra de Victoria, en la Antártida. La región incluye numerosas características geológicas sumamente interesantes tales como el lago Vida y el río Onyx, el río más largo de la Antártida. Además, la zona es uno de los desiertos más secos del mundo.", "url": "https://es.wikipedia.org/wiki/Valles_secos_de_McMurdo"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/Labyrinth%2C_Wright_Valley%2C_McMurdo_Dry_Valleys%2C_Antarctica.jpg/960px-Labyrinth%2C_Wright_Valley%2C_McMurdo_Dry_Valleys%2C_Antarctica.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Labyrinth,_Wright_Valley,_McMurdo_Dry_Valleys,_Antarctica.jpg", "author": "Dturme", "license": "CC BY-SA 4.0", "file": "File:Labyrinth, Wright Valley, McMurdo Dry Valleys, Antarctica.jpg"}}, "mauna_kea": {"en": {"title": "Mauna Kea", "extract": "Mauna Kea is a dormant shield volcano on the island of Hawaiʻi. Its peak is 13,803 feet above sea level, making it the highest point in Hawaii and the island with the second highest high point, behind New Guinea. The peak is about 125 ft (38 m) higher than Mauna Loa, its more massive neighbor. Mauna Kea is unusually topographically prominent for its height: its prominence from sea level is 15th in the world among mountains, at 13,803 ft (4,207.3 m); its prominence from under the ocean is 30,610 ft (9,330 m), rivaled only by Mount Everest. This dry prominence is greater than Everest's height above sea level of 8,848.86 metres or 29,031.7 feet, and some authorities have labeled Mauna Kea the tallest mountain in the world, from its underwater base. Mauna Kea is ranked 8th by topographic isolation.", "url": "https://en.wikipedia.org/wiki/Mauna_Kea"}, "es": {"title": "Mauna Kea", "extract": "Mauna Kea, es un volcán inactivo de la isla de Hawái. Con una altitud de 4207 m s. n. m., es el punto más alto del estado de Hawái.", "url": "https://es.wikipedia.org/wiki/Mauna_Kea"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Mauna_Kea_from_the_ocean.jpg/960px-Mauna_Kea_from_the_ocean.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Mauna_Kea_from_the_ocean.jpg", "author": "Vadim Kurland", "license": "CC BY 2.0", "file": "File:Mauna_Kea_from_the_ocean.jpg"}}, "kau_desert": {"en": {"title": "Kaʻū Desert", "extract": "\nThe Kaʻū Desert is a leeward desert in the district of Kaʻū, the southernmost district on the Big Island of Hawaii, and is made up mostly of dried lava remnants, volcanic ash, sand and gravel. The desert covers an area of the Kīlauea Volcano along the Southwest rift zone. The area lacks any vegetation, mainly due to acid rainfall.", "url": "https://en.wikipedia.org/wiki/Ka%CA%BB%C5%AB_Desert"}, "es": {"title": "Desierto Ka'u", "extract": "El desierto de Kaʻū es un desierto de sotavento en el distrito de Kaʻū, el distrito más al sur de la Isla Grande de Hawái, y se compone principalmente de restos de lava seca, ceniza volcánica, arena y grava. El desierto cubre un área del volcán Kīlauea a lo largo de la zona de rift del suroeste. El área carece de vegetación, principalmente debido a la lluvia ácida.", "url": "https://es.wikipedia.org/wiki/Desierto_Ka'u"}, "photo": {"src": "https://upload.wikimedia.org/wikipedia/commons/9/95/Kau_desert.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "page": "https://commons.wikimedia.org/wiki/File:Kau_desert.jpg", "author": "S.R. Brantley, USGS", "license": "Public domain", "file": "File:Kau_desert.jpg"}}, "svalbard_bockfjorden": {"en": {"title": "Sverrefjellet", "extract": "Sverrefjellet is a mountain in Haakon VII Land at Spitsbergen, Svalbard, at the western side of Bockfjorden. It has a height of 507 m.a.s.l., and is an extinct volcano. Sverrefjellet is named after Sverre Sigurdsson.", "url": "https://en.wikipedia.org/wiki/Sverrefjellet"}, "es": null, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Haakon_VII_Land_Sverrefjellet_Trolltindane_Adolfbreen_Williamstaarnet_behind_Roosflya_IMG_5500.JPG/960px-Haakon_VII_Land_Sverrefjellet_Trolltindane_Adolfbreen_Williamstaarnet_behind_Roosflya_IMG_5500.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Haakon_VII_Land_Sverrefjellet_Trolltindane_Adolfbreen_Williamstaarnet_behind_Roosflya_IMG_5500.JPG", "author": "Bjoertvedt", "license": "CC BY-SA 3.0", "file": "File:Haakon_VII_Land_Sverrefjellet_Trolltindane_Adolfbreen_Williamstaarnet_behind_Roosflya_IMG_5500.JPG"}}, "rio_tinto": {"en": {"title": "Rio Tinto (river)", "extract": "The Río Tinto is a highly toxic river in southwestern Spain that rises in the Sierra Morena mountains of Andalusia. It flows generally south-southwest, reaching the Gulf of Cádiz at Huelva. The Río Tinto river has a unique red and orange colour derived from its extremely acidic chemical makeup with very high levels of iron and heavy metals. The name río tinto means \"coloured river\" in Spanish, in contrast to most rivers, which are clear. However, \"tinto\" is also an expression for red wine in Spain, so it is also related to this second meaning.", "url": "https://en.wikipedia.org/wiki/Rio_Tinto_(river)"}, "es": {"title": "Río Tinto", "extract": "El río Tinto es un río costero del sur de España, que discurre a lo largo de la provincia de Huelva, comunidad autónoma de Andalucía. Nace en la sierra de Padre Caro y tras recorrer casi 100 km llega hasta la ría de Huelva, donde se funde con el Odiel.", "url": "https://es.wikipedia.org/wiki/R%C3%ADo_Tinto"}, "photo": {"src": "https://upload.wikimedia.org/wikipedia/commons/b/b0/Rio_tinto_river_CarolStoker_NASA_Ames_Research_Center.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "page": "https://commons.wikimedia.org/wiki/File:Rio_tinto_river_CarolStoker_NASA_Ames_Research_Center.jpg", "author": "Carol Stoker, NASA", "license": "Public domain", "file": "File:Rio_tinto_river_CarolStoker_NASA_Ames_Research_Center.jpg"}}, "lanzarote": {"en": {"title": "Timanfaya National Park", "extract": "Timanfaya National Park is a Spanish national park in the southwestern part of the island of Lanzarote, in the Canary Islands. It covers parts of the municipalities Tinajo and Yaiza. The area is 51.07 square kilometres (19.72 sq mi), entirely made up of volcanic soil. It is the only National Park in Spain which is entirely geological. The statue El Diablo of César Manrique is its symbol. Timanfaya National Park represents a sign of recent and historical volcanism in the Macaronesian region. The last volcanic eruptions occurred in 1824; however, most of the area covered by the national park was transformed by the eruptive period from 1730 to 1736.", "url": "https://en.wikipedia.org/wiki/Timanfaya_National_Park"}, "es": {"title": "Parque nacional de Timanfaya", "extract": "El parque nacional de Timanfaya es un espacio natural protegido español situado en los municipios de Yaiza y Tinajo, en la isla de Lanzarote, comunidad autónoma de Canarias. En 2021 recibió 803 625 visitantes siendo el segundo parque nacional en número de visitas de Canarias, tras el parque nacional del Teide en Tenerife, así como también es el cuarto de España, tras el del Teide, el de la Sierra de Guadarrama y el de los Picos de Europa.", "url": "https://es.wikipedia.org/wiki/Parque_nacional_de_Timanfaya"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Timanfaya_National_Park_landscape.jpg/960px-Timanfaya_National_Park_landscape.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Timanfaya_National_Park_landscape.jpg", "author": "MiljenkoSuljic", "license": "CC BY-SA 4.0", "file": "File:Timanfaya_National_Park_landscape.jpg"}}, "holuhraun": {"en": {"title": "Holuhraun", "extract": "Holuhraun ( ) is a lava field just north of the Vatnajökull ice cap, in the Icelandic Highlands, in Suður-Þingeyjarsýsla, Northeastern Region, Iceland. The lava field was created by fissure eruptions. After a research expedition in 1880, the lava field was initially called Kvislarhraun. Four years later, it received its current name from geologist and geographer Þorvaldur Thoroddsen.", "url": "https://en.wikipedia.org/wiki/Holuhraun"}, "es": {"title": "Holuhraun", "extract": "Holuhraun es un campo de lava ubicado en Suður-Þingeyjarsýsla, Norðurland Eystra, Islandia. Forma parte de las Tierras Altas de Islandia y se sitúa al norte de Vatnajökull. El campo de lava fue creado por erupciones de fisura. Después de una expedición de investigación en 1880, el campo de lava se llamó inicialmente Kvislarhraun y cuatro años más tarde, recibió su nombre actual por el geólogo y geógrafo, Thorvaldur Thoroddsen.", "url": "https://es.wikipedia.org/wiki/Holuhraun"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/B%C3%A1r%C3%B0arbunga_Volcano%2C_September_4_2014_-_15145875322.jpg/960px-B%C3%A1r%C3%B0arbunga_Volcano%2C_September_4_2014_-_15145875322.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:B%C3%A1r%C3%B0arbunga_Volcano,_September_4_2014_-_15145875322.jpg", "author": "peterhartree", "license": "CC BY-SA 2.0", "file": "File:Bárðarbunga_Volcano,_September_4_2014_-_15145875322.jpg"}}, "mdrs_utah": {"en": {"title": "Mars Desert Research Station", "extract": "The Mars Desert Research Station (MDRS) is the largest and longest-running Mars surface research facility and is one of two simulated Mars analog habitats owned and operated by the Mars Society.", "url": "https://en.wikipedia.org/wiki/Mars_Desert_Research_Station"}, "es": {"title": "Mars Desert Research Station", "extract": "Mars Desert Research Station (MDRS) es el segundo hábitats de simulación para la exploración superficial de Marte de los cuatro planificados por la Mars Society.", "url": "https://es.wikipedia.org/wiki/Mars_Desert_Research_Station"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Mars_Desert_Research_Station_2020.jpg/960px-Mars_Desert_Research_Station_2020.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Mars_Desert_Research_Station_2020.jpg", "author": "The Mars Society / MDRS", "license": "CC BY-SA 4.0", "file": "File:Mars_Desert_Research_Station_2020.jpg"}}, "craters_of_the_moon": {"en": {"title": "Craters of the Moon National Monument and Preserve", "extract": "Craters of the Moon National Monument and Preserve is a U.S. national monument and national preserve in the Snake River Plain in central Idaho. It is along US 20, between the small towns of Arco and Carey, at an average elevation of 5,900 feet (1,800 m) above sea level.", "url": "https://en.wikipedia.org/wiki/Craters_of_the_Moon_National_Monument_and_Preserve"}, "es": null, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/CratersDrone1.jpg/960px-CratersDrone1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:CratersDrone1.jpg", "author": "BroMcjoe", "license": "CC BY-SA 4.0", "file": "File:CratersDrone1.jpg"}}, "meteor_crater": {"en": {"title": "Meteor Crater", "extract": "Meteor Crater, or Barringer Crater, is an impact crater about 37 mi (60 km) east of Flagstaff and 18 mi (29 km) west of Winslow in the desert of northern Arizona, United States. The site had several earlier names, and fragments of the meteorite are officially called the Canyon Diablo Meteorite, after the adjacent Canyon Diablo.", "url": "https://en.wikipedia.org/wiki/Meteor_Crater"}, "es": {"title": "Cráter Barringer", "extract": "El cráter Barringer, también conocido como Meteor Mountain, es el resultado del impacto, hace unos 50 000 años, del llamado meteorito Canyon Diablo. El cráter se localiza a 55 km al este de la ciudad de Flagstaff, en el norte de Arizona, Estados Unidos, siguiendo una salida de la interestatal I-40.", "url": "https://es.wikipedia.org/wiki/Cr%C3%A1ter_Barringer"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Meteor_Crater_-_Arizona.jpg/960px-Meteor_Crater_-_Arizona.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Meteor_Crater_-_Arizona.jpg", "author": "National Map Seamless Server", "license": "Public domain", "file": "File:Meteor_Crater_-_Arizona.jpg"}}, "lonar": {"en": {"title": "Lonar Lake", "extract": "Lonar Lake is a saline, soda lake located near Lonar in Buldhana district of the Indian state of Maharashtra. It occupies an impact crater formed by a hypervelocity meteorite impact. It is the only crater lake of meteoritic origin in the country, and has been designated as a National Geological Monument and a Ramsar site.", "url": "https://en.wikipedia.org/wiki/Lonar_Lake"}, "es": {"title": "Lago Lonar", "extract": "El lago Lonar, también conocido como cráter de Lonar, es un lago salado y carbonatado situado en Lonar, a 79 km de Buldana, en el homónimo distrito del estado indio Maharashtra. Ha sido declarado Monumento Nacional del Patrimonio Geológico.", "url": "https://es.wikipedia.org/wiki/Lago_Lonar"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/Lonar_Crater%2C_Panorama.jpg/960px-Lonar_Crater%2C_Panorama.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Lonar_Crater,_Panorama.jpg", "author": "Aditya Laghate", "license": "CC BY-SA 3.0", "file": "File:Lonar_Crater,_Panorama.jpg"}}, "qaidam": {"en": {"title": "Qaidam Basin", "extract": "The Qaidam, Tsaidam, or Chaidamu Basin is a hyperarid basin that occupies a large part of Haixi Prefecture in Qinghai Province, China. The basin covers an area of approximately 120,000 km2 (46,000 sq mi), one-fourth of which is covered by saline lakes and playas. Around one third of the basin, about 35,000 km2 (14,000 sq mi), is desert.", "url": "https://en.wikipedia.org/wiki/Qaidam_Basin"}, "es": {"title": "Cuenca de Qaidam", "extract": "La cuenca de Qaidam, también transcrita como Tsaidam, es una región desértica del norte de la meseta tibetana, una amplia cuenca o depresión hiper árida. Administrativamente, ocupa una gran parte de la Prefectura autónoma mongol y tibetana de Haixi en la provincia de Qinghai, en el oeste de China. La cuenca cubre un área de aproximadamente 120.000 km², una cuarta parte de ella cubierta por lagos salinos.", "url": "https://es.wikipedia.org/wiki/Cuenca_de_Qaidam"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Yardangs_in_the_Tsaidam_Desert.jpg/960px-Yardangs_in_the_Tsaidam_Desert.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Yardangs_in_the_Tsaidam_Desert.jpg", "author": "John Hill", "license": "CC BY-SA 3.0", "file": "File:Yardangs in the Tsaidam Desert.jpg"}}, "pilbara": {"en": {"title": "Pilbara Craton", "extract": "The Pilbara Craton is an old and stable part of the continental lithosphere located in the Pilbara region of Western Australia.", "url": "https://en.wikipedia.org/wiki/Pilbara_Craton"}, "es": {"title": "Cratón de Pilbara", "extract": "El cratón de Pilbara, forma uno de los terrenos de corteza continental más antiguos de la Tierra. En él se conservan rocas pertenecientes al eón Arcaico. Además de en el cratón de Pilbara, se conocen rocas arcaicas en Groenlandia, Escudo Canadiense, Escudo Báltico, Escocia, India, Brasil, Australia Occidental y Sudáfrica.", "url": "https://es.wikipedia.org/wiki/Crat%C3%B3n_de_Pilbara"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Hamersley_Range%2C_Pilbara_Region%2C_Western_Australia.JPG/960px-Hamersley_Range%2C_Pilbara_Region%2C_Western_Australia.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Hamersley_Range,_Pilbara_Region,_Western_Australia.JPG", "author": "Barry T Coles at English Wikipedia", "license": "Public domain", "file": "File:Hamersley Range, Pilbara Region, Western Australia.JPG"}}, "pisgah": {"en": {"title": "Pisgah Crater", "extract": "Pisgah Crater, or Pisgah Volcano, is a young volcanic cinder cone rising above a lava plain in the Mojave Desert, between Barstow and Needles, California in San Bernardino County, California. The volcanic peak is around 2.5 miles (4.0 km) south of historic U.S. Route 66-National Old Trails Highway and of Interstate 40, and west of the town of Ludlow. The volcano had a historic elevation of 2,638 feet (804 m), but has been reduced to 2,545 feet (776 m) due to mining.", "url": "https://en.wikipedia.org/wiki/Pisgah_Crater"}, "es": null, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Pisgah_Crater_%2825-10-2014%29.JPG/960px-Pisgah_Crater_%2825-10-2014%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Pisgah_Crater_(25-10-2014).JPG", "author": "Member", "license": "CC BY-SA 4.0", "file": "File:Pisgah_Crater_(25-10-2014).JPG"}}, "axel_heiberg": {"en": {"title": "Axel Heiberg Island", "extract": "Axel Heiberg Island is an uninhabited island in the Qikiqtaaluk Region, Nunavut, Canada. Located in the Arctic Ocean, it is the 34th largest island in the world and Canada's ninth largest island. According to the United States Geological Survey, Esri, and the United Nations Environment Programme - World Conservation Monitoring Centre it has an area of 42,276.97 km2 (16,323.23 sq mi). It is named after Axel Heiberg.\nOne of the larger members of the Arctic Archipelago, it is also a member of the Sverdrup Islands and Queen Elizabeth Islands. It is known for its unusual fossil forests, which date from the Eocene period. Owing to the lack of mineralization in many of the forest specimens, the traditional characterization of \"fossilisation\" fails for these forests and \"mummification\" may be a more precise description. The fossil records provide strong evidence that the Axel Heiberg forest was a high-latitude wetland forest. A holotype of the ammonite Otoceras gracile was found in the Griesbachian substage of the Induan age of the Early Triassic deposits of this island.", "url": "https://en.wikipedia.org/wiki/Axel_Heiberg_Island"}, "es": {"title": "Isla Axel Heiberg", "extract": "La isla Axel Heiberg es la séptima isla más grande de Canadá. Forma parte del archipiélago de las islas de la Reina Isabel. Pertenece al Territorio de Nunavut, encontrándose entre las coordenadas 78° y 81° N. y 85° y 97° O en la parte occidental de la isla Ellesmere.", "url": "https://es.wikipedia.org/wiki/Isla_Axel_Heiberg"}, "photo": null}, "ries": {"en": {"title": "Nördlinger Ries", "extract": "The Nördlinger Ries is an impact crater and large circular depression in western Bavaria and eastern Baden-Württemberg. It is located north of the Danube in the district of Donau-Ries. The city of Nördlingen is located within the depression, about 6 kilometres (3.7 mi) south-west of its centre.", "url": "https://en.wikipedia.org/wiki/N%C3%B6rdlinger_Ries"}, "es": {"title": "Ries de Nördlingen", "extract": "Ries de Nördlingen es una región en la frontera entre las sierras del Jura Suabo y del Jura Francón en el triángulo de Núremberg – Stuttgart – Múnich. La denominación Ries proviene del nombre de la provincia romana de «Recia». La ciudad de Nördlingen es el centro de este paisaje perfectamente circular. Durante más de un siglo, los geólogos tuvieron grandes dificultades para explicar el origen del Ries y de sus rocas tan singulares, lo que hizo que a lo largo del tiempo compitieran entre sí interpretaciones muy diversas. Dado que la roca de suevita presente en el Ries se asemeja a la toba volcánica, en un principio se supuso un origen puramente volcánico. En este contexto, Oliver Sachs acuñó los términos \"época pionera\" e \"inicio de la investigación temprana-moderna del Ries\", es decir, el período desde el cual se conocieron las primeras teorías detalladas sobre la formación del Ries de Nördlingen. El Ries de Nördlingen son los restos de un cráter meteorítico de una edad de 14,4 millones de años que proviene del \"Evento del Ries\". Es uno de los cráteres de impacto (astroblemas) mejor conservados de la Tierra.", "url": "https://es.wikipedia.org/wiki/Ries_de_N%C3%B6rdlingen"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Geological_public_collection_-_Alpines_Museum_-_Suevit.JPG/960px-Geological_public_collection_-_Alpines_Museum_-_Suevit.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Geological_public_collection_-_Alpines_Museum_-_Suevit.JPG", "author": "High Contrast", "license": "CC BY 3.0 de", "file": "File:Geological public collection - Alpines Museum - Suevit.JPG"}}, "dhofar": {"en": {"title": "Dhofar", "extract": "Dhofar is the largest of the 11 governorates in the Sultanate of Oman by area. It lies in southwestern Oman, bordered on the west by Al Mahrah Governorate of Yemen, on the north by the Eastern Province of Saudi Arabia, on the east by Al Wusta Governorate, and on the south by the Arabian Sea, part of the Indian Ocean. It is a rather mountainous area that covers 99,300 km2 (38,300 sq mi) and had a population of 416,458 in the 2020 census. Salalah is the largest city and capital of the governorate. Historically, the region was a source of frankincense. The local dialect of Arabic is Dhofari Arabic, which is distinct from that used in the rest of Oman and in Yemen. Many people in Dhofar also speak Modern South Arabian languages.", "url": "https://en.wikipedia.org/wiki/Dhofar"}, "es": {"title": "Gobernación de Dhofar", "extract": "La gobernación de Dhofar o Zufar –en enciclopedias españolas de fines de siglo XIX e inicios del siglo XX el nombre de la región aparece transcripto también como Zafar– se encuentra al suroeste de Omán y al noreste de Yemen. A fines de siglo XIX e inicios de siglo XX su población se consideraba por parte de los antropólogos europeos algo diferenciada de la arábiga ya que se la incluía en la etnia Mahra que llegó a dominar el sultanato de Qishn y Socotora. Históricamente ha sido la fuente principal del incienso en el mundo; sin embargo, este incienso hoy (2015) es usado localmente; Somalia es desde la segunda mitad de siglo XX el principal exportador. Su capital histórica es la ciudad puerto de Mirbat aunque desde los 1970 la mayor ciudad y capital administrativa del gobierno omaní en la región es la también ciudad puerto de Salalah. El llano de Salalah fue una vez un área cultivada con un sofisticado sistema de irrigación. Durante la Primera Guerra Mundial fue suficientemente fértil para producir comida y granos para suplir una gran parte de las necesidades del ejército británico que peleaba en Mesopotamia.", "url": "https://es.wikipedia.org/wiki/Gobernaci%C3%B3n_de_Dhofar"}, "photo": null}, "ramon": {"en": {"title": "Makhtesh Ramon", "extract": "Makhtesh Ramon is a geological feature of Israel's Negev desert. Located some 85 km south of Beersheba, the landform is the world's largest \"erosion cirque\". The formation is 40 km long, 2–10 km wide and 500 meters deep. Despite its appearance, it is not an impact crater from a meteor nor a volcanic crater formed by a volcanic eruption.", "url": "https://en.wikipedia.org/wiki/Makhtesh_Ramon"}, "es": null, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/MakhteshRamonMar262022_01.jpg/960px-MakhteshRamonMar262022_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:MakhteshRamonMar262022_01.jpg", "author": "Hagai Agmon-Snir حچاي اچمون-سنير חגי אגמון-שניר", "license": "CC BY-SA 4.0", "file": "File:MakhteshRamonMar262022_01.jpg"}}, "dome_c": {"en": {"title": "Concordia Station", "extract": "Concordia Research Station, which opened in 2005, is a French–Italian research facility managed by l'Institut polaire français Paul-Émile Victor and Programma Nazionale di Ricerche in Antartide, that was built 3,233 m (10,607 ft) above sea level on a geographical formation known as dôme C, on the Antarctic Plateau, Antarctica. It is located 1,100 km (680 mi) inland from the French research station at Dumont D'Urville, 1,100 km (680 mi) inland from Australia's Casey Station and 1,200 km (750 mi) inland from the Italian Zucchelli Station at Terra Nova Bay. Russia's Vostok Station is 560 km (350 mi) away. The Geographic South Pole is 1,670 km (1,040 mi) away. The facility is also located within Australia's claim on Antarctica, the Australian Antarctic Territory.", "url": "https://en.wikipedia.org/wiki/Concordia_Station"}, "es": {"title": "Base Concordia", "extract": "La base de investigación Concordia, que fue abierta en 2005, es una instalación de investigación operada conjuntamente por científicos de Francia e Italia, que fue construida en un altozano (domo) llamado domo C en la meseta antártica de la Antártida, a 3233 m sobre el nivel del mar. Tiene una pista de aterrizaje de 1500 m para aviones con esquíes, operativa todo el año.", "url": "https://es.wikipedia.org/wiki/Base_Concordia"}, "photo": {"src": "https://upload.wikimedia.org/wikipedia/commons/b/b7/ConcordiaFromTower.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "page": "https://commons.wikimedia.org/wiki/File:ConcordiaFromTower.jpg", "author": "StephenHudson", "license": "Public domain", "file": "File:ConcordiaFromTower.jpg"}}, "dallol": {"en": {"title": "Dallol (hydrothermal system)", "extract": "Dallol is a terrestrial hydrothermal system around a cinder cone volcano in the Danakil Depression, northeast of the Erta Ale Range in Ethiopia. It is known for its unearthly colors and mineral patterns, and the very acidic fluids, commonly noted as some of the most acidic on Earth, that discharge from its hydrothermal springs.", "url": "https://en.wikipedia.org/wiki/Dallol_(hydrothermal_system)"}, "es": {"title": "Dallol", "extract": "Dallol es un cráter volcánico o maar en la depresión de Danakil, al noreste de la cordillera Erta Ale en Etiopía. Se formó por la intrusión de magma basáltico en los depósitos de sal del Mioceno y la actividad hidrotermal posterior. Las erupciones freáticas ocurrieron en 1926, formando el volcán Dallol, mientras que otros cráteres de erupción salpican los salares cercanos. Estos cráteres son los respiraderos volcánicos subaéreos más bajos del mundo, a 45 metros por debajo del nivel del mar.", "url": "https://es.wikipedia.org/wiki/Dallol"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/ET_Afar_asv2018-01_img48_Dallol.jpg/960px-ET_Afar_asv2018-01_img48_Dallol.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:ET_Afar_asv2018-01_img48_Dallol.jpg", "author": "A.Savin", "license": "FAL", "file": "File:ET_Afar_asv2018-01_img48_Dallol.jpg"}}, "lut": {"en": {"title": "Lut Desert", "extract": "Lut Desert is a desert with both extensive salt flats and dunes located in the provinces of Kerman and Sistan-Baluchestan, Iran. It is the world's 33rd-largest desert, and was included in UNESCO's World Heritage List on 17 July 2016.", "url": "https://en.wikipedia.org/wiki/Lut_Desert"}, "es": {"title": "Desierto de Lut", "extract": "El desierto de Lut, o Dasht-e-Lut, es un gran desierto salado localizado en la meseta iraní, en el sureste de Irán.", "url": "https://es.wikipedia.org/wiki/Desierto_de_Lut"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Dasht-e_Lut_Desert_in_Kerman_Province_02.jpg/960px-Dasht-e_Lut_Desert_in_Kerman_Province_02.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Dasht-e_Lut_Desert_in_Kerman_Province_02.jpg", "author": "Ninaras", "license": "CC BY 4.0", "file": "File:Dasht-e_Lut_Desert_in_Kerman_Province_02.jpg"}}, "uyuni": {"en": {"title": "Salar de Uyuni", "extract": "Salar de Uyuni is the largest salt flat in the world, with an area of approximately 10,582 square kilometres (4,086 mi2). It is situated in southwestern Bolivia, within the Daniel Campos Province of the Potosí Department, near the crest of the Andes Mountains, at an elevation of 3,656 m (11,995 ft) above sea level.", "url": "https://en.wikipedia.org/wiki/Salar_de_Uyuni"}, "es": {"title": "Salar de Uyuni", "extract": "El salar de Uyuni, a veces conocido como salar de Tunupa, es el mayor desierto de sal continuo y alto del mundo, con una superficie de 10 582 km². Está situado a unos 3650 m s. n. m. en el suroeste de Bolivia, en la provincia de Daniel Campos del departamento de Potosí, y en la provincia de Ladislao Cabrera del departamento de Oruro, dentro de la región altiplánica de la cordillera de los Andes. El salar de Uyuni es una de las más importantes reservas de litio del mundo e igualmente cuenta con importantes cantidades de potasio, boro y magnesio.", "url": "https://es.wikipedia.org/wiki/Salar_de_Uyuni"}, "photo": {"src": "https://upload.wikimedia.org/wikipedia/commons/4/4a/Salar_Uyuni_au01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "page": "https://commons.wikimedia.org/wiki/File:Salar_Uyuni_au01.jpg", "author": "Anouchka Unel", "license": "FAL", "file": "File:Salar_Uyuni_au01.jpg"}}, "piedra_pomez": {"en": {"title": "Cerro Blanco (volcano)", "extract": "Cerro Blanco is a caldera in the Andes of the Catamarca Province in Argentina. Part of the Central Volcanic Zone of the Andes, it is a volcano collapse structure located at an altitude of 4,670 metres (15,320 ft) in a depression. The caldera is associated with a less well-defined caldera to the south and several lava domes.", "url": "https://en.wikipedia.org/wiki/Cerro_Blanco_(volcano)"}, "es": {"title": "Volcán Robledo", "extract": "Robledo es una caldera volcánica de 6 km de ancho ubicada en la provincia de Catamarca, Argentina, a 80 kilómetros al suroeste del más extenso Cerro Galán. En su interior se localiza el domo conocido como Cerro Blanco. La caldera fue, en el ± 2300 a. C., el lugar de una potente erupción volcánica con IEV-7, Según los datos obtenidos por la Agencia Espacial Europea desde 1992 hasta el 2000, la Caldera Robredo se estaba desinflando por razones que se desconocían.", "url": "https://es.wikipedia.org/wiki/Volc%C3%A1n_Robledo"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Campo_de_piedra_pomez_en_catamarca.jpg/960px-Campo_de_piedra_pomez_en_catamarca.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Campo_de_piedra_pomez_en_catamarca.jpg", "author": "Marioperetti", "license": "CC BY-SA 4.0", "file": "File:Campo de piedra pomez en catamarca.jpg"}}, "pajonales": {"en": {"title": "Salar de Pajonales", "extract": "Salar de Pajonales is a playa in the southern Atacama Region of Chile and the third-largest in that country, behind Salar de Punta Negra and Salar de Atacama. It consists mostly of a gypsum crust; only a small portion of its area is covered with water. During the late Pleistocene, Salar de Pajonales formed an actual lake that has left shoreline features.", "url": "https://en.wikipedia.org/wiki/Salar_de_Pajonales"}, "es": {"title": "Salar de Pajonales", "extract": "El salar de Pajonales es un salar tipo playa ubicado al sur de la Región de Antofagasta y es el tercero de la Región en extensión, después del salar de Atacama y del salar Punta Negra.", "url": "https://es.wikipedia.org/wiki/Salar_de_Pajonales"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/ISS006-E-35457_-_View_of_Chile.jpg/960px-ISS006-E-35457_-_View_of_Chile.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:ISS006-E-35457_-_View_of_Chile.jpg", "author": "Earth Science and Remote Sensing Unit, Lyndon B. Johnson Space Center", "license": "Public domain", "file": "File:ISS006-E-35457_-_View_of_Chile.jpg"}}, "licancabur": {"en": {"title": "Licancabur", "extract": "Licancabur is a prominent, 5,916-metre-high (19,409 ft) stratovolcano on the Bolivia–Chile border in the Central Volcanic Zone of the Andes. It is capped by a 400–500-metre-wide (1,300–1,600 ft) summit crater which contains Licancabur Lake, a crater lake that is among the highest lakes in the world. There are no glaciers owing to the arid climate. Numerous plants and animal species live on the mountain. The volcanoes Sairecabur and Juriques are north and east of Licancabur, respectively.", "url": "https://en.wikipedia.org/wiki/Licancabur"}, "es": {"title": "Volcán Licancabur", "extract": "El volcán Licancabur, también denominado volcán Licancábur es un estratovolcán situado en la frontera entre Bolivia y Chile en la Zona Central Volcánica de los Andes. Está coronado por un cráter de cumbre de 400 a 500 metros de ancho que contiene el lago Licancabur, un lago de cráter que se encuentra entre los lagos más altos del mundo. No existen glaciares debido al clima árido. Numerosas especies de plantas y animales habitan en la montaña. Los volcanes Sairecabur y Juriques se encuentran al norte y al este del Licancabur, respectivamente.", "url": "https://es.wikipedia.org/wiki/Volc%C3%A1n_Licancabur"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Licancabur2.jpg/960px-Licancabur2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Licancabur2.jpg", "author": "Albert Backer", "license": "CC BY-SA 3.0", "file": "File:Licancabur2.jpg"}}, "chimborazo_arenal": {"en": {"title": "Chimborazo", "extract": "Chimborazo is a stratovolcano in Ecuador and the Cordillera Occidental range of the Andes. Its last known eruption is believed to have occurred around AD 550.", "url": "https://en.wikipedia.org/wiki/Chimborazo"}, "es": {"title": "Volcán Chimborazo", "extract": "El Chimborazo es un estratovolcán potencialmente activo, situado en el centro de Ecuador, en la provincia de Chimborazo. Es un volcán muy icónico del Ecuador, hasta el punto de que figura en su escudo. Perteneciente a la cordillera de los Andes, específicamente a los Andes septentrionales, cuenta con una altitud de 6263,47 m s. n. m.; por lo que es la montaña más alta del Ecuador y de los Andes septentrionales.", "url": "https://es.wikipedia.org/wiki/Volc%C3%A1n_Chimborazo"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/Chimborazo%2C_aspecto_norte%2C_Ecuador._%2826354503702%29.jpg/960px-Chimborazo%2C_aspecto_norte%2C_Ecuador._%2826354503702%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Chimborazo,_aspecto_norte,_Ecuador._(26354503702).jpg", "author": "Dick Culbert from Gibsons, B.C., Canada", "license": "CC BY 2.0", "file": "File:Chimborazo,_aspecto_norte,_Ecuador._(26354503702).jpg"}}, "cotopaxi_ash": {"en": {"title": "Cotopaxi", "extract": "Cotopaxi is an active stratovolcano in the Andes Mountains, located in Cotopaxi National Park in Cotopaxi Province, about 50 km (31.1 mi) south of Quito, and 31 km (19 mi) northeast of the city of Latacunga, Ecuador. It is the second highest summit in Ecuador, reaching a height of 5,897 m (19,347 ft). Cotopaxi is among the highest active volcanoes in the world.", "url": "https://en.wikipedia.org/wiki/Cotopaxi"}, "es": {"title": "Volcán Cotopaxi", "extract": "El volcán Cotopaxi es un estratovolcán activo, situado en el centro-norte de Ecuador, en la provincia de Cotopaxi. Perteneciente a la cordillera de los Andes, específicamente a los Andes septentrionales, cuenta con una altitud de 5897 m s. n. m.; por lo que es la segunda montaña más alta del Ecuador y de los Andes septentrionales, sólo superado por el volcán Chimborazo.", "url": "https://es.wikipedia.org/wiki/Volc%C3%A1n_Cotopaxi"}, "photo": {"src": "https://upload.wikimedia.org/wikipedia/commons/2/20/Cotopaxi_volcano_2008-06-27T1322.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "page": "https://commons.wikimedia.org/wiki/File:Cotopaxi_volcano_2008-06-27T1322.jpg", "author": "Gerard Prins", "license": "CC BY-SA 3.0", "file": "File:Cotopaxi_volcano_2008-06-27T1322.jpg"}}, "sierra_negra": {"en": {"title": "Sierra Negra (Galápagos)", "extract": "Sierra Negra is a large shield volcano at the southeastern end of Isabela Island in the Galapagos that rises to an altitude of 1124m. It coalesces with the volcanoes Cerro Azul to the west and Alcedo to the north. It is one of the most active of the Galapagos volcanoes with the most recent historic eruption beginning in June 2018 and continuing through the summer.", "url": "https://en.wikipedia.org/wiki/Sierra_Negra_(Gal%C3%A1pagos)"}, "es": {"title": "Sierra Negra (Ecuador)", "extract": "Sierra Negra es el nombre que recibe un extenso volcán en escudo en el extremo suroriental de la isla Isabela en las islas Galápagos, Ecuador que se eleva a una altitud de 1124 metros sobre el nivel del mar. se une con el volcán de Cerro Azul hacia el oeste y hacia el norte con el de Alcedo. Es uno de los volcanes más activos de Galápagos con la erupción más reciente en 2016 en el mes de diciembre y en junio del 2018. Hay extensos flujos de lava entre la Sierra Negra y la ciudad de Puerto Villamil.", "url": "https://es.wikipedia.org/wiki/Sierra_Negra_(Ecuador)"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Galapagos-Sierra_Negra_2005_October_22.jpg/960px-Galapagos-Sierra_Negra_2005_October_22.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Galapagos-Sierra_Negra_2005_October_22.jpg", "author": "NASA image created by Jesse Allen, Earth Observatory, using data obtained courtesy of the MODIS Rapid Response Team (NOA", "license": "Public domain", "file": "File:Galapagos-Sierra_Negra_2005_October_22.jpg"}}, "fernandina": {"en": {"title": "Fernandina Island", "extract": "Fernandina Island is the youngest and third largest island in the Galápagos, as well as the furthest west. It has an area of 642 km2 (248 sq mi) and a height of 1,476 m (4,843 ft), with a summit caldera about 6.5 km (4.0 mi) wide. It is younger than Isabela, being only less than one million years old since its formation. Like the other islands, it was formed by the Galápagos hotspot. The island is an active shield volcano that has most recently erupted in March 2024.", "url": "https://en.wikipedia.org/wiki/Fernandina_Island"}, "es": {"title": "Isla Fernandina", "extract": "Fernandina es una isla perteneciente al Ecuador, ubicada en las islas Galápagos, en el océano Pacífico. Es la tercera más grande del archipiélago tras Isabela y Santa Cruz. Uno de los volcanes más activos del mundo se encuentra en esta isla.", "url": "https://es.wikipedia.org/wiki/Isla_Fernandina"}, "photo": {"src": "https://upload.wikimedia.org/wikipedia/commons/e/e3/Fernandina_isabela.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "page": "https://commons.wikimedia.org/wiki/File:Fernandina_isabela.jpg", "author": "NASA", "license": "Public domain", "file": "File:Fernandina_isabela.jpg"}}, "tolbachik": {"en": {"title": "Tolbachik", "extract": "Tolbachik is a volcanic complex on the Kamchatka Peninsula in the far east of Russia. It consists of two volcanoes, Plosky (flat) Tolbachik and Ostry (sharp) Tolbachik, which as the names suggest are respectively a flat-topped shield volcano and a peaked stratovolcano. As Ostry is the mountain's highest point, the entire mountain is often referred to as \"Ostry Tolbachik\", not to be confused with Ostry, a separate volcano to the north also on the Kamchatka Peninsula.", "url": "https://en.wikipedia.org/wiki/Tolbachik"}, "es": {"title": "Tolbachik", "extract": "El Tolbáchik  es un volcán complejo en la península de Kamchatka, Rusia. Se compone de dos volcanes, un volcán en escudo con una cumbre aplanada y un estratovolcán con una cumbre puntiaguda. Como Ostry es el punto más elevado de la montaña, el volcán complejo entero es a menudo denominado \"Ostry Tolbáchik\". No debe confundirse con Ostry, otro volcán, situado más en el norte de la península de Kamchatka.", "url": "https://es.wikipedia.org/wiki/Tolbachik"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Tolbatschik_aus_S%C3%BCdwesten.jpg/960px-Tolbatschik_aus_S%C3%BCdwesten.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Tolbatschik_aus_S%C3%BCdwesten.jpg", "author": "Leo Palkovics", "license": "CC BY-SA 3.0", "file": "File:Tolbatschik_aus_Südwesten.jpg"}}, "namib": {"en": {"title": "Namib", "extract": "The Namib is a coastal desert in Southern Africa. According to the broadest definition, the Namib stretches for more than 2,000 kilometres (1,200 mi) along the Atlantic coasts of Angola, Namibia, and northwest South Africa, extending southward from the Carunjamba River in Angola, through Namibia and to the Olifants River in Western Cape, South Africa. The Namib's northernmost portion, which extends 450 kilometres (280 mi) from the Angola-Namibia border, is known as Moçâmedes Desert, while its southern portion approaches the neighboring Kalahari Desert. From the Atlantic coast eastward, the Namib gradually ascends in elevation, reaching up to 200 kilometres (120 mi) inland to the foot of the Great Escarpment. Annual precipitation ranges from 2 millimetres (0.079 in) in the aridest regions to 200 millimetres (7.9 in) at the escarpment, making the Namib the only true desert in southern Africa. Having endured arid or semi-arid conditions for roughly 55–80 million years, the Namib may be the oldest desert in the world and contains some of the world's driest regions, with only western South America's Atacama Desert to challenge it for age and aridity benchmarks. Most of Namibia's share of the Namib Desert is protected under the environmental protection included in the constitution of the country.", "url": "https://en.wikipedia.org/wiki/Namib"}, "es": {"title": "Desierto del Namib", "extract": "El desierto del Namib es un importante desierto de África que se extiende a lo largo de la costa de Namibia, entre el río Orange, que marca la frontera con la República de Sudáfrica, al sur, y el río Kunene, entre Namibia y Angola, al norte. Tiene una longitud de unos 2000 km, una anchura que varía entre 80 y 200 km y una extensión cercana a los 81 000 km². Su nombre, Namib, significa en lengua nama «enorme».", "url": "https://es.wikipedia.org/wiki/Desierto_del_Namib"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/Namib_desert_MODIS.jpg/960px-Namib_desert_MODIS.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Namib_desert_MODIS.jpg", "author": "Jeff Schmaltz, MODIS Land Rapid Response Team, NASA GSFC", "license": "Public domain", "file": "File:Namib_desert_MODIS.jpg"}}, "gilf_kebir": {"en": {"title": "Gilf Kebir", "extract": "Gilf Kebir is a plateau in the New Valley Governorate of the remote southwest corner of Egypt, and southeast Libya. Its name translates as \"the Great Barrier\". This 7,770 km2 (3,000 sq mi) sandstone plateau, roughly the size of Puerto Rico, rises 300 m (980 ft) from the Libyan Desert floor. It is the true heart of the Gilf Kebir National Park.", "url": "https://en.wikipedia.org/wiki/Gilf_Kebir"}, "es": {"title": "Meseta de Gilf Kebir", "extract": "Gilf Kebir es una meseta en la gobernación de Nuevo Valle del rincón suroeste de Egipto, y al sureste de Libia. Su nombre se traduce como \"la Gran Barrera\". Esta meseta de composición de arenisca de unos 7.770 km², de aproximadamente el tamaño de Puerto Rico, se eleva a 300 metros del suelo sobre el desierto Líbico.", "url": "https://es.wikipedia.org/wiki/Meseta_de_Gilf_Kebir"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/GilfKebir1.jpg/960px-GilfKebir1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:GilfKebir1.jpg", "author": "Clemens Schmillen", "license": "CC BY-SA 4.0", "file": "File:GilfKebir1.jpg"}}, "changtang": {"en": {"title": "Changtang", "extract": "The Changtang is a part of the high altitude Tibetan Plateau in western and northern Tibet extending into the southern edges of Xinjiang as well as Changthang district in southeastern Ladakh of India, with highlands and lakes. From eastern Ladakh, the Changtang stretches approximately 1,600 kilometres (990 mi) east into Tibet as far as modern Qinghai. The Changtang is home to the Changpa, a nomadic Tibetan people. The two largest settlements within the Tibetan Changtang are Rutog Town, which is the seat of Rutog County, and Domar Township, the seat of Shuanghu County.", "url": "https://en.wikipedia.org/wiki/Changtang"}, "es": {"title": "Changtang", "extract": "La región de Changtang es una parte de la meseta tibetana, al oeste y el norte del Tíbet, que se extiende desde los límites meridionales de la región autónoma de Sinkiang, en China, hasta el sudeste de la región india de Ladakh, con vastas tierras altas y grandes lagos. Desde la parte oriental de Ladakh, el Changtang se extiende unos 1600 km hacia el este en el Tíbet, hasta la moderna Qinghai. El Changtang es la patria de los changpa, un pueblo tibetano nómada. Los dos asentamientos más grandes dentro del tibetano Changtang son la ciudad de Rutog, sede del condado de Rutog, y el municipio de Domar, sede del condado de Shuanghu.[cita requerida]", "url": "https://es.wikipedia.org/wiki/Changtang"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Changpas_nomadic_people_-_Changtang_-_Tibet.jpg/960px-Changpas_nomadic_people_-_Changtang_-_Tibet.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Changpas_nomadic_people_-_Changtang_-_Tibet.jpg", "author": "6-A04-W96-K38-S41-V38", "license": "CC BY-SA 4.0", "file": "File:Changpas_nomadic_people_-_Changtang_-_Tibet.jpg"}}, "miller_range": {"en": {"title": "Miller Range", "extract": "The Miller Range is a mountain range extending south from Nimrod Glacier for 80 km (50 mi) along the western edge of the Marsh Glacier in Antarctica.", "url": "https://en.wikipedia.org/wiki/Miller_Range"}, "es": null, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Miller_Range%2C_Antarctica_-_Searching_for_meteorites_%282%29.jpg/960px-Miller_Range%2C_Antarctica_-_Searching_for_meteorites_%282%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Miller_Range,_Antarctica_-_Searching_for_meteorites_(2).jpg", "author": "NASA/Cindy Evans", "license": "Public domain", "file": "File:Miller_Range,_Antarctica_-_Searching_for_meteorites_(2).jpg"}}, "tenoumer": {"en": {"title": "Tenoumer crater", "extract": "Tenoumer is a probable impact crater in Mauritania.", "url": "https://en.wikipedia.org/wiki/Tenoumer_crater"}, "es": null, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Tenoumer_Krater.jpg/960px-Tenoumer_Krater.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Tenoumer_Krater.jpg", "author": "Michael Dennig", "license": "Public domain", "file": "File:Tenoumer_Krater.jpg"}}, "aorounga": {"en": {"title": "Aorounga crater", "extract": "Aorounga Crater is an impact crater in Chad. The exposed remnant of the crater is 12.6 km (7.8 mi) in diameter and its age is estimated to be less than 345 million years.", "url": "https://en.wikipedia.org/wiki/Aorounga_crater"}, "es": null, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/ISS020-E-026195_Aorounga_Impact_Crater_Chad.jpg/960px-ISS020-E-026195_Aorounga_Impact_Crater_Chad.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:ISS020-E-026195_Aorounga_Impact_Crater_Chad.jpg", "author": "NASA Expedition 20 crew\nImage Science & Analysis Laboratory, NASA Johnson Space Center\nDerivative work including grading", "license": "Public domain", "file": "File:ISS020-E-026195_Aorounga_Impact_Crater_Chad.jpg"}}, "wolfe_creek": {"en": {"title": "Wolfe Creek Crater", "extract": "Wolfe Creek Crater is a well-preserved meteorite impact crater (astrobleme) in Western Australia.", "url": "https://en.wikipedia.org/wiki/Wolfe_Creek_Crater"}, "es": {"title": "Cráter Wolfe Creek", "extract": "El cráter Wolfe Creek es un cráter de impacto de meteorito (astroblema), bastante bien conservado, de Australia Occidental. Situado dentro del Parque Nacional Wolfe Creek Meteorite Crater, se encuentra a 105 km en línea recta al sur de la ciudad de Halls Creek, la población más cercana.", "url": "https://es.wikipedia.org/wiki/Cr%C3%A1ter_Wolfe_Creek"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Wolfe_creek_crater.jpg/960px-Wolfe_creek_crater.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Wolfe_creek_crater.jpg", "author": "Unknown", "license": "Public domain", "file": "File:Wolfe_creek_crater.jpg"}}, "payun_matru": {"en": {"title": "Payún Matrú", "extract": "Payún Matrú is a shield volcano in the Reserva Provincial La Payunia of the Malargüe Department, south of the Mendoza Province in Argentina. It lies in the back-arc region of the Andean Volcanic Belt, and was formed by the subduction of the Nazca Plate beneath the South American Plate. Payún Matrú, along with the Llancanelo, Nevado and Salado Basin volcanic fields, form the Payenia province. It has been proposed as a World Heritage Site since 2011.", "url": "https://en.wikipedia.org/wiki/Pay%C3%BAn_Matr%C3%BA"}, "es": {"title": "Payún Matrú", "extract": "El Payún Matrú es un gran volcán de tipo morfológico intermedio entre un escudo volcánico y un estratovolcán de la Argentina, situado en el departamento de Malargüe, en el sur de la provincia de Mendoza.", "url": "https://es.wikipedia.org/wiki/Pay%C3%BAn_Matr%C3%BA"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Pay%C3%BAn_Volcanic_Field_%288347075230%29.jpg/960px-Pay%C3%BAn_Volcanic_Field_%288347075230%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Pay%C3%BAn_Volcanic_Field_(8347075230).jpg", "author": "NASA Goddard Space Flight Center from Greenbelt, MD, USA", "license": "Public domain", "file": "File:Payún_Volcanic_Field_(8347075230).jpg"}}, "harrat_khaybar": {"en": {"title": "Harrat Khaybar", "extract": "Ḥarrat Khaybar is a volcanic field located north of Medina in the Hejaz, Saudi Arabia. It covers an area approximately 12,000 km2 (4,600 sq mi). The most recent eruption occurred between 600 and 700 AD. Man-made stone structures dating to the Neolithic period have been studied in Harrat Khaybar.", "url": "https://en.wikipedia.org/wiki/Harrat_Khaybar"}, "es": null, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4c/%D8%AD%D8%B1%D8%A9_%D8%AE%D9%8A%D8%A8%D8%B1.jpg/960px-%D8%AD%D8%B1%D8%A9_%D8%AE%D9%8A%D8%A8%D8%B1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:%D8%AD%D8%B1%D8%A9_%D8%AE%D9%8A%D8%A8%D8%B1.jpg", "author": "NASA Earth Observatory images by Lauren Dauphin, using Landsat data from the U.S. Geological Survey. Story by Emily Cass", "license": "Public domain", "file": "File:حرة_خيبر.jpg"}}, "undara": {"en": {"title": "Undara Volcanic National Park", "extract": "The Undara Volcanic National Park is a national park in the Shire of Etheridge, Queensland, Australia. It is situated 275 kilometres (171 mi) southwest of Cairns just off the Gulf Developmental Road. The park was established in 1989 to protect Australia's longest lava tube and the unique fauna and flora found of the area. The basalts of the area form part of the Cenozoic McBride Basalt (Volcanic) Province. The volcanics are all less than 8 million years old (Ma) with the youngest only 7,000 years old.", "url": "https://en.wikipedia.org/wiki/Undara_Volcanic_National_Park"}, "es": {"title": "Parque nacional Undara Volcánico", "extract": "Undara Volcánico es un parque nacional en Queensland (Australia), ubicado a 1339 km al noroeste de Brisbane.", "url": "https://es.wikipedia.org/wiki/Parque_nacional_Undara_Volc%C3%A1nico"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/Undara_Lava_Tubes_-_panoramio_%2811%29.jpg/960px-Undara_Lava_Tubes_-_panoramio_%2811%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Undara_Lava_Tubes_-_panoramio_(11).jpg", "author": "Lobster1", "license": "CC BY-SA 3.0", "file": "File:Undara_Lava_Tubes_-_panoramio_(11).jpg"}}, "emi_koussi": {"en": {"title": "Emi Koussi", "extract": "Emi Koussi, also known as Emi Koussou, is a high pyroclastic shield volcano that lies at the southeast end of the Tibesti Mountains in the central Sahara, in the northern Borkou Region of northern Chad. The highest mountain of the Sahara, the volcano is one of several in the Tibesti range, and reaches an elevation of 3,447 metres (11,309 ft), rising 3 km (1.9 mi) above the surrounding sandstone plains. The volcano is 60–70 kilometres (37–43 mi) wide and has a volume of 2,500 cubic kilometres (600 cu mi).", "url": "https://en.wikipedia.org/wiki/Emi_Koussi"}, "es": {"title": "Emi Koussi", "extract": "Emi Koussi es un volcán en escudo que se encuentra en el sur de las montañas Tibesti en la zona central del Sahara en el norte del Chad. Es la montaña más alta del Chad, y la más alta en el Sahara. El volcán es uno de varios en el macizo de Tibesti, tiene 3445 m de altura, elevándose unos 2,3 km por sobre las planicies que lo rodean. El volcán posee una base de 60 km por 80 km.", "url": "https://es.wikipedia.org/wiki/Emi_Koussi"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Emi_Koussi_Volcano%2C_Chad_From_ISS.JPG/960px-Emi_Koussi_Volcano%2C_Chad_From_ISS.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Emi_Koussi_Volcano,_Chad_From_ISS.JPG", "author": "ISS Expedition 26 crew", "license": "Public domain", "file": "File:Emi_Koussi_Volcano,_Chad_From_ISS.JPG"}}, "rub_al_khali": {"en": {"title": "Rub' al Khali", "extract": "The Rub' al Khali is a desert encompassing most of the southern third of the Arabian Peninsula. The desert covers some 650,000 km2 (250,000 sq mi), including parts of Saudi Arabia, Oman, the United Arab Emirates, and Yemen. It is part of the larger Arabian Desert.", "url": "https://en.wikipedia.org/wiki/Rub'_al_Khali"}, "es": {"title": "Desierto de Rub al-Jali", "extract": "El desierto de Rub al-Jali o al Rab al Khali es uno de los mayores desiertos de arena del mundo, formando parte del más amplio desierto de Arabia. Administrativamente, comprende la mayor parte del tercio meridional de la península arábiga, entre Arabia Saudita, Omán, los Emiratos Árabes Unidos y Yemen. Tiene una extensión de unos 650 000 km², y se sitúa entre los 44°30′ y los 56°30′ E de longitud, y entre los 16°30′ y los 23°00′ N de latitud.", "url": "https://es.wikipedia.org/wiki/Desierto_de_Rub_al-Jali"}, "photo": {"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Rub_al_Khali_002.JPG/960px-Rub_al_Khali_002.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "page": "https://commons.wikimedia.org/wiki/File:Rub_al_Khali_002.JPG", "author": "Nepenthes", "license": "CC BY-SA 3.0", "file": "File:Rub_al_Khali_002.JPG"}}};
